messages.content:
```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "pelaku-ekonomi-run", title: "Pelaku Ekonomi Run", seed: "pelaku-ekonomi-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Ekonomi",
    concept: "Tiga pelaku kegiatan ekonomi: rumah tangga konsumen, rumah tangga produsen, dan pemerintah",
    objectives: [
      "Mengelompokkan kegiatan ekonomi berdasarkan pelaku yang tepat",
      "Memahami bahwa pemerintah juga melakukan kegiatan konsumsi dan produksi"
    ],
    misconceptions: [
      "Pemerintah tidak termasuk pelaku ekonomi karena hanya mengatur, bukan melakukan kegiatan ekonomi"
    ],
    mode: "category",
    categories: [
      { id: "konsumen",  label: "Rumah Tangga Konsumen", color: "#2F80ED" },
      { id: "produsen",  label: "Rumah Tangga Produsen", color: "#3FA34D" },
      { id: "pemerintah", label: "Pemerintah",           color: "#E5A100" }
    ],
    items: [
      { id: "beli-pasar",     label: "Membeli barang di pasar", category: "konsumen",   explain: "Rumah tangga membeli barang untuk memenuhi kebutuhan konsumsi." },
      { id: "bayar-listrik",  label: "Membayar listrik",        category: "konsumen",   explain: "Membayar jasa untuk kebutuhan konsumsi rumah tangga." },
      { id: "menabung",       label: "Menabung di bank",        category: "konsumen",   explain: "Menyisihkan pendapatan untuk konsumsi masa depan." },
      { id: "produksi-pabrik", label: "Memproduksi barang di pabrik", category: "produsen", explain: "Menghasilkan barang untuk dijual kepada konsumen." },
      { id: "bayar-upah",     label: "Membayar upah karyawan",  category: "produsen",   explain: "Balas jasa atas faktor produksi tenaga kerja." },
      { id: "buka-warung",    label: "Membuka usaha warung",    category: "produsen",   explain: "Menjalankan kegiatan produksi dan penjualan barang." },
      { id: "pungut-pajak",   label: "Memungut pajak",          category: "pemerintah", explain: "Pajak adalah sumber pendapatan negara untuk membiayai pembangunan." },
      { id: "bangun-jalan",   label: "Membangun jalan raya",    category: "pemerintah", explain: "Pemerintah menyediakan fasilitas publik bagi masyarakat." },
      { id: "gaji-pns",       label: "Membayar gaji pegawai negeri", category: "pemerintah", explain: "Pemerintah bertindak sebagai pemberi kerja dan pengonsumsi." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game **Pelaku Ekonomi Run** adalah Endless Runner edukasi bertema Clean Modern dengan tiga kategori pelaku ekonomi. Asumsi penting: item jebakan "Membayar gaji pegawai negeri" sengaja masuk kategori Pemerintah untuk meluruskan miskonsepsi bahwa pemerintah hanya mengatur, bukan berperan ekonomi.
